import pandas as pd, numpy as np, re
from statsmodels.tsa.filters.hp_filter import hpfilter

def annual_series(df):
    s={}
    for _, row in df.iterrows():
        label=str(row[0]).strip()
        m=re.match(r'^(\d{4})\.?$', label)
        if m:
            s[int(m.group(1))]=float(row[1])
    # 2024 average of available quarterly rows after 2024: I.
    idxs=df.index[df[0].astype(str).str.contains('^2024:')].tolist()
    if idxs:
        start=idxs[0]
        vals=[]
        for i in range(start, min(start+4, len(df))):
            try:
                vals.append(float(df.iloc[i,1]))
            except:
                pass
        s[2024]=sum(vals)/len(vals)
    return pd.Series(s).sort_index()

pce=annual_series(pd.read_excel('/root/ERP-2025-table10.xls', header=None))
pfi=annual_series(pd.read_excel('/root/ERP-2025-table12.xls', header=None))
cpi=pd.read_excel('/root/CPI.xlsx').set_index('Year')['CPI_2024']
idx=range(1973,2025)
pce=pce.loc[idx]; pfi=pfi.loc[idx]; cpi=cpi.loc[idx]
real_pce=pce/cpi; real_pfi=pfi/cpi
cycle_pce,_=hpfilter(np.log(real_pce), lamb=100)
cycle_pfi,_=hpfilter(np.log(real_pfi), lamb=100)
cor=float(np.corrcoef(cycle_pce, cycle_pfi)[0,1])
print(cor)
